/**
 * Spoken digit recordings + matching speech-shaped noise (one pack per language).
 * Generated by scripts/generate_din_audio.py: every digit is RMS-equalised to the
 * same level as the noise, so gain differences equal the signal-to-noise ratio.
 * To use studio recordings, replace the WAV files and the sample offsets below.
 */
import type { Lang } from '../../lib/i18n'
import { devHooks, getCtx, loadBuffer, playBufferSegment, playLoop } from '../../lib/audio'
import dinEn from '../../assets/audio/din-en.wav'
import dinRu from '../../assets/audio/din-ru.wav'
import dinUz from '../../assets/audio/din-uz.wav'
import noiseEn from '../../assets/audio/noise-en.wav'
import noiseRu from '../../assets/audio/noise-ru.wav'
import noiseUz from '../../assets/audio/noise-uz.wav'

const SR = 22050
/** [start, length] in samples for digits 0–9. */
const OFFSETS: Record<Lang, [number, number][]> = {
  en: [[0, 10560], [12765, 7920], [22890, 7700], [32795, 7040], [42040, 9020], [53265, 9900], [65370, 8360], [75935, 8360], [86500, 7260], [95965, 10340]],
  ru: [[0, 8580], [10785, 10780], [23770, 11660], [37635, 6820], [46660, 12540], [61405, 9900], [73510, 10340], [86055, 10780], [99040, 13200], [114445, 10780]],
  uz: [[0, 8192], [10397, 14592], [27194, 15360], [44759, 13056], [60020, 9580], [71805, 8360], [82370, 9764], [94339, 16060], [112604, 15360], [130169, 10665]],
}
const FILES: Record<Lang, { speech: string; noise: string }> = {
  en: { speech: dinEn, noise: noiseEn },
  ru: { speech: dinRu, noise: noiseRu },
  uz: { speech: dinUz, noise: noiseUz },
}

/** Noise bed level (gain applied to the RMS-normalised files). */
export const NOISE_GAIN_DB = -12

export interface DigitPack {
  lang: Lang
  speech: AudioBuffer
  noise: AudioBuffer
}

export async function loadDigitPack(lang: Lang): Promise<DigitPack> {
  const [speech, noise] = await Promise.all([loadBuffer(FILES[lang].speech), loadBuffer(FILES[lang].noise)])
  return { lang, speech, noise }
}

export const digitDuration = (lang: Lang, d: number) => OFFSETS[lang][d][1] / SR

/**
 * Play digits (optionally in noise). Returns the AudioContext time when playback ends.
 * @param snr speech level relative to the noise, dB. `null` = no noise (quiet).
 */
export function playDigits(pack: DigitPack, digits: number[], snr: number | null, opts: { gap?: number; lead?: number; speechGainDb?: number } = {}) {
  const ctx = getCtx()
  if (import.meta.env.DEV) devHooks.lastDigits = { digits, snr }
  const gap = opts.gap ?? 0.35
  const lead = opts.lead ?? 0.5
  const t0 = ctx.currentTime + 0.08
  let t = t0 + (snr === null ? 0.05 : lead)
  const speechGain = opts.speechGainDb ?? (snr === null ? NOISE_GAIN_DB + 6 : NOISE_GAIN_DB + snr)
  for (const d of digits) {
    const [start, len] = OFFSETS[pack.lang][d]
    playBufferSegment(pack.speech, { offset: start / SR, duration: len / SR, when: t, gainDb: speechGain })
    t += len / SR + gap
  }
  const end = t - gap + (snr === null ? 0.05 : 0.35)
  if (snr !== null) {
    const loop = playLoop(pack.noise, NOISE_GAIN_DB, t0)
    loop.stop(end)
  }
  return { start: t0, end }
}

/** Play a single digit at time `when` (used by the auditory digit span). */
export function playDigitAt(pack: DigitPack, d: number, when: number, gainDb = NOISE_GAIN_DB + 6) {
  const [start, len] = OFFSETS[pack.lang][d]
  playBufferSegment(pack.speech, { offset: start / SR, duration: len / SR, when, gainDb })
  return when + len / SR
}
